import { toMatchImageSnapshot } from "jest-image-snapshot";
import { type TestRunnerConfig } from "@storybook/test-runner";
import { getStoryContext, waitForPageReady } from "@storybook/test-runner";

// This file has info which is responsible for running snapshot(dom) testing and visual regression testing

const customSnapshotIdentifier =
  (theme) =>
    ({ currentTestName, counter }) => {
      const id = `${currentTestName}-${counter}`
        .toLocaleLowerCase()
        .replace(/[\s&]+/g, "-");
      const parts = id.split("/");
      const category = parts!.shift().replace(`storyshots-${theme}-`, "");
      return `${theme}/${category}/${parts.join("--")}`;
    };

let brand = process.env.ADS_VISUAL_BRAND;
const customSnapshotsDir = `${process.cwd()}/src/_visualregression_/__image_snapshots__/`;
let config: TestRunnerConfig = {}
if (brand) {
  // visual testing
  config = {
    tags: {
      include: ["visual-test"],
      skip: ["skip-test"], //test runner, skips test if stories file has this tag
    },
    setup() {
      // jest.retryTimes(RETRY_TIMES, { logErrorsBeforeRetry: true })
      // jest.setTimeout(JEST_TIMEOUT_MS)
      if (brand) {
        // @ts-ignore
        expect.extend({ toMatchImageSnapshot });
      }
    },
    /* Hook to execute before a story is initially visited before being rendered in the browser.
     * The page argument is the Playwright's page object for the story.
     * The context argument is a Storybook object containing the story's id, title, and name.
     */
    async preVisit(page, context) {
      const DEFAULT_VIEWPORT_SIZE = { width: 800, height: 600 };
      page.setViewportSize(DEFAULT_VIEWPORT_SIZE);

    },
    /* Hook to execute after a story is visited and fully rendered.
     * The page argument is the Playwright's page object for the story
     * The context argument is a Storybook object containing the story's id, title, and name.
     */
    async postVisit(page, context) {
      await getStoryContext(page, context);
      // Modify the theme using Storybook's global state
      await page.evaluate((theme) => {
        // Access Storybook's global state
        const channel = (window as any).__STORYBOOK_ADDONS_CHANNEL__
        // Update the global theme
        channel.emit('updateGlobals', {
          globals: {
            theme: theme // or 'dumdum', depending on your test
          }
        });
      }, brand);

      // uncomment to read comments from browser
      // page.on('console', (msg) => console.log(msg.text()))

      await waitForPageReady(page);

      const image = await page.screenshot(); // wait for the page to be fully loaded, including all the async items

      // @ts-ignore-next-line
      expect(image).toMatchImageSnapshot({
        customSnapshotsDir,
        customSnapshotIdentifier: customSnapshotIdentifier(brand),
        blur: 3,
        failureThreshold: 0.005,
        failureThresholdType: "percent",
        customDiffConfig: {
          threshold: 0.25, // per pixel failure threshold (default 0.1)
          includeAA: false,
        },
      });
    },
  };
}
else {
  console.log("No brand specified, skipping visual regression testing");
  // snapshot(dom) testing
  config = {
    tags: {
      skip: ["skip-test"], //test runner, skips test if stories file has this tag
    },
    async preVisit(page, context) {
      const DEFAULT_VIEWPORT_SIZE = { width: 800, height: 600 };
      page.setViewportSize(DEFAULT_VIEWPORT_SIZE);

    },
    async postVisit(page, context) {
      await getStoryContext(page, context);
      await waitForPageReady(page);
      const elementHandler = await page.$("#storybook-root"); // the #storybook-root element wraps the story.
      const innerHTML = await elementHandler!.innerHTML();
      // @ts-ignore
      expect(innerHTML).toMatchSnapshot();
    },
  };
}

export default config;
